-- Stints for Mexico City 2026 and Monza 2026
INSERT INTO stints (race_id, driver_id, stint_no, compound_id, start_lap, end_lap)
SELECT r.race_id, d.driver_id, v.stint, v.cid, v.slap, v.elap
FROM (VALUES
 (2026, 20, 'NOR', 1, 2, 1, 31),
 (2026, 20, 'NOR', 2, 3, 32, 71),
 (2026, 20, 'LEC', 1, 2, 1, 30),
 (2026, 20, 'LEC', 2, 3, 31, 71),
 (2026, 20, 'VER', 1, 2, 1, 28),
 (2026, 20, 'VER', 2, 3, 29, 71),
 (2026, 15, 'ANT', 1, 2,  1, 26),
 (2026, 15, 'ANT', 2, 3, 27, 53),
 (2026, 15, 'RUS', 1, 2,  1, 22),
 (2026, 15, 'RUS', 2, 3, 23, 53),
 (2026, 15, 'HAM', 1, 1,  1, 15),
 (2026, 15, 'HAM', 2, 2, 16, 36),
 (2026, 15, 'HAM', 3, 3, 37, 53),
 (2026, 15, 'LEC', 1, 2,  1, 12),
 (2026, 15, 'VER', 1, 3,  1, 30),
 (2026, 15, 'VER', 2, 2, 31, 53)
) AS v(yr, rnd, code, stint, cid, slap, elap)
JOIN races r ON r.season = v.yr AND r.round_no = v.rnd
JOIN drivers d ON d.code = v.code;

-- Pit Stops
INSERT INTO pit_stops (race_id, driver_id, stop_no, lap_no, pit_duration_s, stationary_time_s, tyre_fitted_id, crew_penalty_s)
SELECT r.race_id, d.driver_id, v.stop_no, v.lap_no, v.dur, v.stat, v.tyre, v.pen
FROM (VALUES
 (2026, 20, 'NOR', 1, 31, 22.4, 2.1, 3, 0.0),
 (2026, 20, 'LEC', 1, 30, 22.8, 2.3, 3, 0.0),
 (2026, 20, 'VER', 1, 28, 23.1, 2.4, 3, 0.0),
 (2026, 15, 'ANT', 1, 26, 24.1, 2.4, 3, 0.0),
 (2026, 15, 'RUS', 1, 22, 24.5, 2.6, 3, 0.0),
 (2026, 15, 'HAM', 1, 15, 23.9, 2.2, 2, 0.0),
 (2026, 15, 'HAM', 2, 36, 24.0, 2.3, 3, 0.0),
 (2026, 15, 'VER', 1, 30, 24.8, 2.9, 2, 0.0)
) AS v(yr, rnd, code, stop_no, lap_no, dur, stat, tyre, pen)
JOIN races r ON r.season = v.yr AND r.round_no = v.rnd
JOIN drivers d ON d.code = v.code;

-- Telemetry
INSERT INTO lap_telemetry (race_id, driver_id, lap_no, lap_time_s, sector1_s, sector2_s, sector3_s, tyre_age_laps, is_pit_lap)
SELECT r.race_id, d.driver_id, v.lap_no, v.t, v.s1, v.s2, v.s3, v.age, v.pit
FROM (VALUES
 (2026, 20, 'NOR', 1,  79.40, 26.2, 26.4, 26.8, 1,  FALSE),
 (2026, 20, 'NOR', 2,  78.10, 25.8, 26.0, 26.3, 2,  FALSE),
 (2026, 20, 'NOR', 31, 101.50, 26.1, 48.9, 26.5, 31, TRUE),
 (2026, 20, 'NOR', 32, 78.50, 25.9, 26.2, 26.4, 1,  FALSE),
 (2026, 15, 'ANT', 1,  84.50, 27.8, 28.1, 28.6, 1,  FALSE),
 (2026, 15, 'ANT', 2,  82.10, 27.1, 27.4, 27.6, 2,  FALSE),
 (2026, 15, 'ANT', 26, 106.20, 27.5, 51.2, 27.5, 26, TRUE),
 (2026, 15, 'ANT', 27, 82.90, 27.3, 27.7, 27.9, 1,  FALSE)
) AS v(yr, rnd, code, lap_no, t, s1, s2, s3, age, pit)
JOIN races r ON r.season = v.yr AND r.round_no = v.rnd
JOIN drivers d ON d.code = v.code;

-- Initial plan for Interlagos 2026
INSERT INTO strategy_plans (track_id, weather_id, stops, delta_s)
SELECT t.track_id, 1, 2, 0.0
FROM tracks t WHERE t.slug = 'interlagos';

INSERT INTO plan_stints (plan_id, stint_no, compound_id, stint_laps)
SELECT currval('strategy_plans_plan_id_seq'), 1, 2, 24
UNION ALL
SELECT currval('strategy_plans_plan_id_seq'), 2, 3, 24
UNION ALL
SELECT currval('strategy_plans_plan_id_seq'), 3, 2, 23;

